let systemDatabase = { teams: [], members: {}, deoHistory: [], eventStartDate: "", eventEndDate: "" };
let activeTeamId = "";
let draggedRowIndex = null;
let tokenCount = Date.now();

const TEAM_COLOR_MAP = {
    "team a": "bg-emerald-500/15 border-emerald-500 text-emerald-300",
    "team b": "bg-blue-500/15 border-blue-500 text-blue-300",
    "team c": "bg-amber-500/15 border-amber-500 text-amber-300",
    "team d": "bg-purple-500/15 border-purple-500 text-purple-300",
    "team e": "bg-rose-500/15 border-rose-500 text-rose-300",
    "team g": "bg-yellow-500/15 border-yellow-500 text-yellow-300"
};

function createUniqueId() { tokenCount++; return 'uid_' + tokenCount + '_' + Math.random().toString(36).substring(2, 6); }

function initSystemEngine() {
    let savedData = localStorage.getItem('THAI_HU_UPGRADED_RUNTIME_DB') || localStorage.getItem('THAI_HU_PERSIST_DB');
    if (savedData) {
        try {
            let runtimeCache = JSON.parse(savedData);
            if (runtimeCache.teams && runtimeCache.members) {
                systemDatabase = runtimeCache;
                if (!systemDatabase.deoHistory) systemDatabase.deoHistory = [];
                activeTeamId = systemDatabase.teams[0]?.id || "";
                evaluateLineupsDynamicCapacity();
                refreshUserInterfaceLayout(); return;
            }
        } catch(e) { console.error(e); }
    }
    if (localStorage.getItem('THAI_HU_CUSTOM_DEFAULT_TEMPLATE')) {
        try {
            systemDatabase = JSON.parse(localStorage.getItem('THAI_HU_CUSTOM_DEFAULT_TEMPLATE'));
            if (!systemDatabase.deoHistory) systemDatabase.deoHistory = [];
            Object.keys(systemDatabase.members).forEach(k => systemDatabase.members[k].currentRuns = 0);
            activeTeamId = systemDatabase.teams[0]?.id || "";
            evaluateLineupsDynamicCapacity();
            refreshUserInterfaceLayout(); return;
        } catch(e) { console.error(e); }
    }
    parseAndLoadFromPayloadTemplate(HARDCODED_FACTORY_SEED);
}

function parseAndLoadFromPayloadTemplate(sourcePayload) {
    systemDatabase.teams = []; systemDatabase.members = {}; systemDatabase.deoHistory = [];
    sourcePayload.forEach(t => {
        let teamId = t.id || createUniqueId();
        let teamObj = { id: teamId, name: t.name, type: 'data', memberIds: [] };
        t.rows.forEach(r => {
            let mId = createUniqueId();
            systemDatabase.members[mId] = { id: mId, name: r.acc ? r.acc.trim() : "", maxRuns: 3, currentRuns: 0, originalTeamId: teamId, isEditing: false, freeRun2: false, freeRun3: false, skipStatNL: false };
            teamObj.memberIds.push(mId);
        });
        while(teamObj.memberIds.length < 8) {
            let mId = createUniqueId();
            systemDatabase.members[mId] = { id: mId, name: "", maxRuns: 3, currentRuns: 0, originalTeamId: teamId, isEditing: true, freeRun2: false, freeRun3: false, skipStatNL: false };
            teamObj.memberIds.push(mId);
        }
        systemDatabase.teams.push(teamObj);
    });
    activeTeamId = systemDatabase.teams[0]?.id || "";
    evaluateLineupsDynamicCapacity();
    refreshUserInterfaceLayout(); saveStateToMemoryCache();
}

// --- HÀM LẤY NGÀY GMT+7 HÀ NỘI ---
function getVietnamCurrentDateString() {
    return new Intl.DateTimeFormat('en-CA', { 
        timeZone: 'Asia/Ho_Chi_Minh', 
        year: 'numeric', 
        month: '2-digit', 
        day: '2-digit' 
    }).format(new Date());
}

// --- TỰ ĐỘNG LƯU: RUNTIME + SNAPSHOT RIÊNG TỪNG NGÀY ---
function saveStateToMemoryCache() { 
    localStorage.setItem('THAI_HU_UPGRADED_RUNTIME_DB', JSON.stringify(systemDatabase)); 
    
    const todayStr = getVietnamCurrentDateString();
    const dailySnapshotPackage = {
        saveDate: todayStr,
        lastUpdated: new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }),
        systemDatabase: systemDatabase,
        settings: {
            materialPrice: document.getElementById('input-material-price')?.value || "0.15",
            goldRate: document.getElementById('input-gold-rate')?.value || "155.000",
            ticketPrice: document.getElementById('input-ticket-price')?.value || "24",
            refundPrice: document.getElementById('input-refund-price')?.value || "15"
        }
    };
    localStorage.setItem('THAIHU_SNAPSHOT_' + todayStr, JSON.stringify(dailySnapshotPackage));

    let historyDays = JSON.parse(localStorage.getItem('THAIHU_HISTORY_INDEX') || '[]');
    if (!historyDays.includes(todayStr)) {
        historyDays.push(todayStr);
        localStorage.setItem('THAIHU_HISTORY_INDEX', JSON.stringify(historyDays));
    }
    localStorage.setItem('THAIHU_LAST_ACTIVE_DAY', todayStr);

    calculateRealtimeProfits(); 
}

function refreshUserInterfaceLayout() {
    renderNavigationSubTabs(); renderActiveWorkspacePanel(); 
    if (typeof updateDeoStatisticsDisplays === 'function') { updateDeoStatisticsDisplays(); }
    if (typeof renderDeoHistoryLedger === 'function') { renderDeoHistoryLedger(); }
    document.getElementById('input-event-start-date').value = systemDatabase.eventStartDate || "";
    document.getElementById('input-event-end-date').value = systemDatabase.eventEndDate || "";
    updateEventRangeLabel();
}

function formatVNDInput(input) { let numeric = input.value.replace(/\D/g, ""); input.value = numeric.replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function getParsedVNDValue(str) { return parseFloat((str||"").replace(/\./g, "")) * 1000 || 0; }

function saveCurrentAsDefaultTemplate() { localStorage.setItem('THAI_HU_CUSTOM_DEFAULT_TEMPLATE', JSON.stringify(systemDatabase)); alert("Đã lưu mẫu cấu hình cố định!"); }
function resetToHardcodedDefault() {
    if(confirm("Khôi phục danh sách gốc ban đầu của hệ thống?")) {
        localStorage.removeItem('THAI_HU_UPGRADED_RUNTIME_DB'); localStorage.removeItem('THAI_HU_CUSTOM_DEFAULT_TEMPLATE');
        systemDatabase.deoHistory = []; parseAndLoadFromPayloadTemplate(HARDCODED_FACTORY_SEED);
    }
}
function resetDailyRunsOnly() {
    if(confirm("Xác nhận reset toàn bộ số lượt ngày hôm nay về 0? Các ngày trước đó vẫn lưu an toàn.")) {
        saveStateToMemoryCache(); // Chốt sổ snapshot ngày hôm nay trước khi đưa về 0
        Object.keys(systemDatabase.members).forEach(id => systemDatabase.members[id].currentRuns = 0);
        evaluateLineupsDynamicCapacity(); 
        refreshUserInterfaceLayout(); 
        saveStateToMemoryCache();
    }
}

function toggleFloatingProfitCard() { document.getElementById('floating-profit-card').classList.toggle('hidden'); }
function toggleFloatingDeoCard() { document.getElementById('floating-deo-card').classList.toggle('hidden'); }

function evaluateLineupsDynamicCapacity() {
    let capacityTracker = {};
    Object.keys(systemDatabase.members).forEach(mId => {
        let m = systemDatabase.members[mId];
        if(m && m.name) { capacityTracker[mId] = m.maxRuns - m.currentRuns; }
    });

    systemDatabase.teams.forEach(team => {
        if (team.type !== 'lineup') return;
        let alreadySelectedInThisTeam = [];
        
        team.memberIds.forEach((mId, idx) => {
            if (!mId) return;
            if (alreadySelectedInThisTeam.includes(mId)) {
                team.memberIds[idx] = ""; return;
            }

            if (capacityTracker[mId] && capacityTracker[mId] > 0) {
                capacityTracker[mId]--;
                alreadySelectedInThisTeam.push(mId);
            } else {
                team.memberIds[idx] = ""; 
            }
        });
    });
}

function calculateRealtimeProfits() {
    let materialPrice = parseFloat(document.getElementById('input-material-price').value) || 0;
    let goldRateVnd = getParsedVNDValue(document.getElementById('input-gold-rate').value);
    let ticketPrice = parseFloat(document.getElementById('input-ticket-price').value) || 0;
    let refundPrice = parseFloat(document.getElementById('input-refund-price').value) || 16; 
    let includeDeo = document.getElementById('checkbox-toggle-include-deo').checked;
    let excludeRefund = document.getElementById('checkbox-toggle-exclude-refund').checked;
    
    let totalRuns = 0, totalMaterials = 0, totalTicketCostGold = 0;

    Object.keys(systemDatabase.members).forEach(mId => {
        let m = systemDatabase.members[mId]; if (!m || !m.name) return;
        let runs = m.currentRuns, max = m.maxRuns; totalRuns += runs;
        
        if (!m.skipStatNL) {
            if (runs >= 1) totalMaterials += 24; if (runs >= 2) totalMaterials += 48; if (runs >= 3) totalMaterials += 48;
        }
        
        if (runs >= 2) {
            if (m.freeRun2) { totalTicketCostGold += 0; }
            else { 
                let backGold = excludeRefund ? 0 : refundPrice;
                totalTicketCostGold += (max === 2) ? Math.max(0, ticketPrice - backGold) : ticketPrice; 
            }
        }
        if (runs >= 3) {
            if (m.freeRun3) { totalTicketCostGold += 0; }
            else {
                let backGold = excludeRefund ? 0 : refundPrice;
                totalTicketCostGold += Math.max(0, ticketPrice - backGold);
            }
        }
    });

    let finalNetGoldValue = (totalMaterials * materialPrice) - totalTicketCostGold + (includeDeo && typeof getDeoValueInTimeframe === 'function' ? getDeoValueInTimeframe('today') : 0);
    let finalNetVndValue = (finalNetGoldValue / 1000) * goldRateVnd;

    document.querySelectorAll('[id="runtime-total-runs"]').forEach(el => el.innerText = totalRuns);
    document.querySelectorAll('[id="runtime-total-materials"]').forEach(el => el.innerText = totalMaterials + " nl");
    document.querySelectorAll('[id="runtime-total-costs"]').forEach(el => el.innerText = totalTicketCostGold.toFixed(1) + "v");
    let profitLabel = document.getElementById('runtime-net-profit-gold');
    profitLabel.innerText = `${finalNetGoldValue >= 0 ? '+' : ''}${finalNetGoldValue.toFixed(2)} Vàng`;
    document.getElementById('runtime-net-profit-vnd').innerText = `~ ${Math.round(finalNetVndValue).toLocaleString('vi-VN')} VND`;
    profitLabel.className = finalNetGoldValue >= 0 ? "text-sm font-black text-emerald-400 block" : "text-sm font-black text-rose-400 block";
}

function toggleFreeRunState(memberId, runNumber, isChecked) {
    let m = systemDatabase.members[memberId];
    if (m) {
        if (runNumber === 2) m.freeRun2 = isChecked;
        if (runNumber === 3) m.freeRun3 = isChecked;
        evaluateLineupsDynamicCapacity(); calculateRealtimeProfits(); saveStateToMemoryCache(); renderActiveWorkspacePanel();
    }
}

function toggleSkipStatNLState(memberId, isChecked) {
    let m = systemDatabase.members[memberId];
    if (m) {
        m.skipStatNL = isChecked;
        calculateRealtimeProfits(); saveStateToMemoryCache(); renderActiveWorkspacePanel();
    }
}

function checkTeamHasCriticalRebateMember(teamObj) {
    let isCritical = false;
    teamObj.memberIds.forEach(mId => {
        let m = systemDatabase.members[mId];
        if(m && m.name) {
            if ((m.maxRuns === 2 && m.currentRuns === 1) || (m.maxRuns === 3 && m.currentRuns === 2)) { isCritical = true; }
        }
    });
    return isCritical;
}

function renderNavigationSubTabs() {
    let container = document.getElementById('sub-tabs-bar-holder'); container.innerHTML = ""; if(!systemDatabase.teams) return;
    systemDatabase.teams.forEach(t => {
        let btn = document.createElement('button');
        let isCriticalDataTeam = (t.type === 'data' && checkTeamHasCriticalRebateMember(t));
        let criticalClass = isCriticalDataTeam ? 'border-red-500 bg-red-950/40 text-rose-400 animate-pulse font-black' : (activeTeamId === t.id ? 'bg-blue-600/20 text-blue-400 border-blue-500 shadow-inner' : 'bg-gray-700/40 text-gray-400 border-gray-700 hover:bg-gray-700');
        
        btn.className = `px-3 py-1.5 rounded-lg border text-[11px] font-bold transition flex items-center gap-1.5 cursor-pointer ${criticalClass}`;
        let icon = t.type === 'lineup' ? 'fa-shuffle text-purple-400' : 'fa-users text-emerald-400';
        btn.innerHTML = `<i class="fa-solid ${icon}"></i> ${t.name.toUpperCase()} ${isCriticalDataTeam ? '<span class="w-1.5 h-1.5 rounded-full bg-red-500 block"></span>' : ''}`;
        btn.onclick = () => { activeTeamId = t.id; renderNavigationSubTabs(); renderActiveWorkspacePanel(); }; container.appendChild(btn);
    });
}

